import chess

MOTIF_NAME = 'dangerous advanced passed pawn'
MOTIF_DESCRIPTION = 'The side to move owns a clearly more dangerous passed pawn than the opponent - advanced, unblockaded, with a clear or well controlled promotion path and pawn, neighbour-passer or heavy-piece support - while not being down material.'

_V = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.2, chess.ROOK: 5.0, chess.QUEEN: 9.0}


def _mat(b, c):
    t = 0.0
    for pt in _V:
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _rel(sq, c):
    r = chess.square_rank(sq)
    return r if c == chess.WHITE else 7 - r


def _is_passed(b, sq, c, d, o):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    for df in (-1, 0, 1):
        nf = f + df
        if nf < 0 or nf > 7:
            continue
        rr = r + d
        while 0 <= rr <= 7:
            p = b.piece_at(chess.square(nf, rr))
            if p is not None and p.piece_type == chess.PAWN and p.color == o:
                return False
            rr += d
    return True


def _value(b, sq, c, d, o):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    v = float(_rel(sq, c))
    stop = chess.square(f, r + d)
    sp = b.piece_at(stop)
    if sp is not None:
        v -= 1.5 if sp.color == o else 0.5
    na = len(b.attackers(o, stop))
    nd = len(b.attackers(c, stop))
    if na > nd:
        v -= 1.0
    elif nd > na:
        v += 0.5
    clear = True
    rr = r + d
    while 0 <= rr <= 7:
        if b.piece_at(chess.square(f, rr)) is not None:
            clear = False
            break
        rr += d
    if clear:
        v += 0.5
    br = r - d
    if 0 <= br <= 7:
        for df in (-1, 1):
            nf = f + df
            if 0 <= nf <= 7:
                p = b.piece_at(chess.square(nf, br))
                if p is not None and p.color == c and p.piece_type == chess.PAWN:
                    v += 0.75
                    break
    rr = r - d
    while 0 <= rr <= 7:
        p = b.piece_at(chess.square(f, rr))
        if p is not None:
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                v += 0.5 if p.color == c else -0.5
            break
        rr -= d
    return v


def _best(b, c):
    o = not c
    d = 1 if c == chess.WHITE else -1
    sqs = []
    for sq in b.pieces(chess.PAWN, c):
        rl = _rel(sq, c)
        if rl < 2 or rl > 6:
            continue
        if _is_passed(b, sq, c, d, o):
            sqs.append(sq)
    files = set()
    for s in sqs:
        files.add(chess.square_file(s))
    best = 0.0
    for sq in sqs:
        v = _value(b, sq, c, d, o)
        f = chess.square_file(sq)
        if (f - 1) in files or (f + 1) in files:
            v += 0.75
        if v > best:
            best = v
    return best


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if _mat(b, us) < _mat(b, them) - 0.5:
        return False
    bu = _best(b, us)
    if bu < 3.5:
        return False
    return bu - _best(b, them) >= 1.5
